WITH unpacked AS (SELECT id, effective_from, tier_prices, discounts, ARRAY_MIN(tier_prices) AS lowest_price, ELEMENT_AT(tier_prices, 1) AS entry_price, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps FROM price_tiers WHERE effective_from >= '2025-08-22') SELECT id, lowest_price, ROW_NUMBER() OVER (ORDER BY lowest_price, id) seq_no, LAG(entry_price, 2) OVER (ORDER BY effective_from, id) prev_entry_price, LAG(entry_price, 1) OVER (PARTITION BY DATE_TRUNC('month', effective_from) ORDER BY entry_price, id) prev_entry_price_2, ROW_NUMBER() OVER (ORDER BY lowest_price, id) seq_no_2, SUM(lowest_price) OVER (ORDER BY effective_from, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) cumulative_lowest_price FROM unpacked
